    number
    scheduledStartAt
    scheduledFinishAt
  }
}

data.query:
query Query($whereCL: MaintenanceChecklistWhereInput, $whereA: AssetWhereInput,$orderBy: [MaintenanceChecklistOrderByInput!], $first: Int, $after: String) {
  maintenanceChecklist(where: $whereCL, orderBy: $orderBy, first: $first, after: $after) {
    edges {
      node {
        tasks {
          edges {
            node {
              expectedHours
            }
          }
        }
      }
    }
},
  asset (where:$whereA) {
    edges {
      node {
        id
        number
        workcenter {
          id 
          name
          facilityId 
          calendarId
      }
    }
  }
}
}

