data.transform:
(

  /*   $moment($state.context.REQUEST.DATA.startAt).isAfter($moment()) ? 
      $moment($state.context.REQUEST.DATA.startAt) : (
      $m := $moment().diff($state.context.REQUEST.DATA.startAt,"months");
      $moment($state.context.REQUEST.DATA.startAt).add($m,'month');
     ); */
    $L := $state.context.LOCAL;
    $R := $state.context.REQUEST.DATA;
    $a := $L.asset;
    $d := $R.startAt;
    $c := [{
      "id":"Maintenance",
      "eid" : $cuid()
    },{
      "id":$a.workcenter.calendarId,
      "eid":$cuid()
    }];
    $w := $state.context.LOCAL.workOrder;
    $wid := $cuid();
    $gid := $cuid();

{
  "payloadWO":{
    "create": {
      "id": $wid,
      "number": "M." & $a.number & "." & $moment($d).format('MMDDYYYY') & "." &  $uppercase($substring($wid, 20)),
      "transactionAt": $now(),
      "scheduledStartAt": $d,
      "scheduledFinishAt": $moment($d).add($L.totalEstimatedTime, 'hours'),
      "workOrderTypeId": "Maintenance",
      "workOrderStatusId": "Released",
      "maintenanceChecklistId": $R.checklistId,
      "facilityId": $a.workcenter.facilityId,
      "originalQuantity":0,
      "quantity":0
    }
  },
  "payloadDG": {
      "create": {
        "id": $gid,
        "number": "M." & $a.number & "." & $moment($d).format('MMDDYYYY') & "." &  $uppercase($substring($wid, 20)),
        "estimatedTime": $L.totalEstimatedTime,
        "scheduledStartAt": $d,
        "scheduledFinishAt":$moment($d).add($L.totalEstimatedTime, 'hours'),
        "workOrderProcessDistributionStatusId": "New",
        "assetId": $a.id
      }
    },
    "payloadC": $c.{
      "create": {
        "id": eid,
        "calendarId": id,
        "priority":0,
        "calendarEventTypeId": "unavailable",
        "title": $a.number & "-Monthly Maintenance",
        "description": $a.number & "-Monthly Maintenance",
        "eventJson": {
          "allDay": false,
          "recurring": false,
          "start": $d,
          "end": $moment($d).add($L.totalEstimatedTime, 'hours')
        }
      }
    },
    "payloadD": $c[1].{
      "create": {
        "estimatedTime": $L.totalEstimatedTime,
        "scheduledStartAt": $d,
        "scheduledFinishAt": $moment($d).add($L.totalEstimatedTime, 'hours'),
        "workOrderId": $wid,
        "assetId": $a.id,
        "workcenterId": $a.workcenter.id,
        "distributionGroupId": $gid,
        "workOrderProcessDistributionStatusId": "New",
        "calendarEventId": eid
      }
    }
}
)

